template <typename T>
struct hash<facebook::react::RectangleEdges<T>> {
  size_t operator()(
      const facebook::react::RectangleEdges<T>& edges) const noexcept {
    return facebook::react::hash_combine(
        edges.left, edges.right, edges.top, edges.bottom);
  }
};

