struct range_traits_char_ {
  template <typename Value>
  using apply = std::char_traits<Value>;
};
struct range_traits_byte_ {
  template <typename Value>
  struct apply {
    inline __attribute__((__always_inline__)) __attribute__((__visibility__("hidden"))) static constexpr bool eq(Value a, Value b) { return a == b; }

    inline __attribute__((__always_inline__)) __attribute__((__visibility__("hidden"))) static constexpr int compare(
        Value const* a, Value const* b, std::size_t c) {
      return !c ? 0 : std::memcmp(a, b, c);
    }
  };
};
struct range_traits_fbck_ {
  template <typename Value>
  struct apply {
    inline __attribute__((__always_inline__)) __attribute__((__visibility__("hidden"))) static constexpr bool eq(Value a, Value b) { return a == b; }

    inline __attribute__((__always_inline__)) __attribute__((__visibility__("hidden"))) static constexpr int compare(
        Value const* a, Value const* b, std::size_t c) {
      while (c--) {
        auto&& ai = *a++;
        auto&& bi = *b++;
        if (ai < bi) {
          return -1;
        }
        if (bi < ai) {
          return +1;
        }
      }
      return 0;
    }
  };
};

