template <typename T>
struct hash<facebook::react::RectangleCorners<T>> {
  size_t operator()(
      const facebook::react::RectangleCorners<T>& corners) const noexcept {
    return facebook::react::hash_combine(
        corners.topLeft,
        corners.bottomLeft,
        corners.topRight,
        corners.bottomRight);
  }
};

